class Vector {
  constructor(xf, yf, zf, xi = 0, yi = 0, zi = 0) {
    this.xi = xi;
    this.yi = yi;
    this.zi = zi;
    this.xf = xf;
    this.yf = yf;
    this.zf = zf;
  }

  getLength = () => {
    return Math.sqrt((this.xf - this.xi) ** 2 + (this.yf - this.yi) ** 2 + (this.zf - this.zi) ** 2);
  };

  getDirectional = () => {
    let length = this.getLength();
    return { x: (this.xf - this.xi) / length, y: (this.yf - this.yi) / length, z: (this.zf - this.zi) / length };
  };

  changeDirection = () => {
    let xi = Number(this.xi);
    let yi = Number(this.yi);
    let zi = Number(this.zi);
    this.xi = Number(this.xf);
    this.yi = Number(this.yf);
    this.zi = Number(this.zf);
    this.xf = Number(xi);
    this.yf = Number(yi);
    this.zf = Number(zi);
  };

  print = () => {
    console.log(`(${this.xi}, ${this.yi}, ${this.zi}) -> (${this.xf}, ${this.yf}, ${this.zf})`);
  };

  /**
   * Returns global {x, y, z} coordinates of the end point of the resized vector
   * @param {*} new_length
   * @returns
   */
  resizeVector = (new_length) => {
    let dir_vector = this.getDirectional();
    return { x: this.xi + dir_vector.x * new_length, y: this.yi + dir_vector.y * new_length, z: this.zi + dir_vector.z * new_length };
  };

  /**
   * Calculate a point perpendicular to the vector in the vertical plane
   * @param {"start"|"end"} position - From the start or the ens point of the vector
   * @param {"positive"|"negative"} direction - Positive or negative with respect to the vector
   * @param {*} length - Perpendicular distance to the new point
   * @returns {x:Number, y: Number, z:Number}
   */
  getPerpendicularVerticalPoint = (position, direction, length = 1) => {
    let dir_vector = this.getDirectional();
    let vert_vector = { x: 0, y: 0, z: direction === "positive" ? 1 : -1 };
    if (dir_vector.x === 0 && dir_vector.y === 0) {
      vert_vector.x = direction === "positive" ? 1 : -1;
      vert_vector.z = 0;
    }
    let perp_out_vector = cross_product(dir_vector, vert_vector);
    let perp_vert_vector = cross_product(perp_out_vector, dir_vector);
    let scaled_point = scale_point(perp_vert_vector, length / point_distance(perp_vert_vector));
    if (position === "start") {
      return {
        x: this.xi + scaled_point.x,
        y: this.yi + scaled_point.y,
        z: this.zi + scaled_point.z,
      };
    } else {
      return {
        x: this.xf + scaled_point.x,
        y: this.yf + scaled_point.y,
        z: this.zf + scaled_point.z,
      };
    }
  };
}

/**
 *
 * @param {Vector} vector
 * @param {Number} vector_size - Actual length of the arrow
 * @param {"start"|"end"} arrow_pos - Where to place the arrow head
 */
function getPlotableArrow(vector, vector_size, arrow_pos = "start", arrow_body_factor = 0.2, alpha = 15) {
  let plot_coords = { x: [], y: [], z: [] };
  if (vector.getLength() !== 0) {
    alpha = (alpha * Math.PI) / 180;
    let far_coords = vector.resizeVector(vector_size);
    let resized_vector = new Vector(far_coords.x, far_coords.y, far_coords.z, vector.xi, vector.yi, vector.zi);
    if (arrow_pos === "end") resized_vector.changeDirection();
    let x_close = resized_vector.xi;
    let y_close = resized_vector.yi;
    let z_close = resized_vector.zi;
    let x_far = resized_vector.xf;
    let y_far = resized_vector.yf;
    let z_far = resized_vector.zf;
    // Arrow body far point
    plot_coords.x.push(x_far);
    plot_coords.y.push(y_far);
    plot_coords.z.push(z_far);
    // Arrow body node point
    plot_coords.x.push(x_close);
    plot_coords.y.push(y_close);
    plot_coords.z.push(z_close);
    // Arrow line up
    let perp_coords_up = resized_vector.getPerpendicularVerticalPoint("end", "positive", vector_size * Math.tan(alpha));
    let arrow_vector_up = new Vector(perp_coords_up.x, perp_coords_up.y, perp_coords_up.z, x_close, y_close, z_close);
    let arrow_coords_up = arrow_vector_up.resizeVector(arrow_body_factor * vector_size);
    plot_coords.x.push(arrow_coords_up.x);
    plot_coords.y.push(arrow_coords_up.y);
    plot_coords.z.push(arrow_coords_up.z);
    // Arrow line down
    let perp_coords_down = resized_vector.getPerpendicularVerticalPoint("end", "negative", vector_size * Math.tan(alpha));
    let arrow_vector_down = new Vector(perp_coords_down.x, perp_coords_down.y, perp_coords_down.z, x_close, y_close, z_close);
    let arrow_coords_down = arrow_vector_down.resizeVector(arrow_body_factor * vector_size);
    plot_coords.x.push(x_close);
    plot_coords.y.push(y_close);
    plot_coords.z.push(z_close);
    plot_coords.x.push(arrow_coords_down.x);
    plot_coords.y.push(arrow_coords_down.y);
    plot_coords.z.push(arrow_coords_down.z);
    // Arrow body node point
    plot_coords.x.push(x_close);
    plot_coords.y.push(y_close);
    plot_coords.z.push(z_close);
    // Arrow body far point
    plot_coords.x.push(x_far);
    plot_coords.y.push(y_far);
    plot_coords.z.push(z_far);
  } else {
    let x_close = vector.xi;
    let y_close = vector.yi;
    let z_close = vector.zi;
    plot_coords.x.push(x_close);
    plot_coords.y.push(y_close);
    plot_coords.z.push(z_close);
  }
  return plot_coords;
}

function cross_product(point_1, point_2) {
  return {
    x: point_1.y * point_2.z - point_1.z * point_2.y,
    y: point_1.z * point_2.x - point_1.x * point_2.z,
    z: point_1.x * point_2.y - point_1.y * point_2.x,
  };
}

function dot_product(point_1, point_2) {
  return point_1.x * point_2.x + point_1.y * point_2.y + point_1.z * point_2.z;
}

function scale_point(point, scalar) {
  return {
    x: point.x * scalar,
    y: point.y * scalar,
    z: point.z * scalar,
  };
}

function point_distance(point) {
  return Math.sqrt(point.x ** 2 + point.y ** 2 + point.z ** 2);
}

/**
 *
 * @param {Vector} vector_1
 * @param {Vector} vector_2
 * @returns
 */
function getMostPerpendicularAxisToPlane(vector_1, vector_2) {
  let perp_point = cross_product(vector_1.getDirectional(), vector_2.getDirectional());
  let perp_vector = new Vector(perp_point.x, perp_point.y, perp_point.z);
  let plotly_x = new Vector(1, 0, 0);
  let plotly_y = new Vector(0, 1, 0);
  let plotly_z = new Vector(0, 0, 1);

  let plotly_x_angle = Math.abs(
    dot_product(plotly_x.getDirectional(), perp_vector.getDirectional()) / (plotly_x.getLength() * perp_vector.getLength())
  );
  let plotly_y_angle = Math.abs(
    dot_product(plotly_y.getDirectional(), perp_vector.getDirectional()) / (plotly_y.getLength() * perp_vector.getLength())
  );
  let plotly_z_angle = Math.abs(
    dot_product(plotly_z.getDirectional(), perp_vector.getDirectional()) / (plotly_z.getLength() * perp_vector.getLength())
  );

  let angles_array = [plotly_x_angle, plotly_y_angle, plotly_z_angle];

  return ["x", "y", "z"][angles_array.indexOf(Math.max(...angles_array))];
}

/**
 *
 * @param {Array<import("./submodules/paramele-parsers/types").s3d_node>} nodes_list
 */
function findNotParallelVectorsInNodesList(nodes_list) {
  for (let node_index = 0; node_index < nodes_list.length; node_index++) {
    const total_nodes = nodes_list.length;
    let node_1 = nodes_list[node_index];
    let node_2 = nodes_list[node_index + 1];
    let node_3 = nodes_list[node_index + 2];
    if (node_index === total_nodes - 2) node_3 = nodes_list[0];
    if (node_index === total_nodes - 1) {
      node_2 = nodes_list[0];
      node_3 = nodes_list[1];
    }

    let vector_1 = new Vector(node_1.x, node_1.y, node_1.z, node_2.x, node_2.y, node_2.z);
    let vector_2 = new Vector(node_3.x, node_3.y, node_3.z, node_2.x, node_2.y, node_2.z);
    let vector_1_dir = vector_1.getDirectional();
    let vector_2_dir = vector_2.getDirectional();
    let cross_vector = cross_product(vector_1_dir, vector_2_dir);
    let cross_norm = new Vector(cross_vector.x, cross_vector.y, cross_vector.z).getLength();
    if (cross_norm !== 0) {
      return {
        vector_1,
        vector_2,
      };
    }
  }
  throw new Error("It was not possible to find not in line consecutive points");
}

const geom_utils = { Vector, getPlotableArrow, getMostPerpendicularAxisToPlane, cross_product, findNotParallelVectorsInNodesList };

export default geom_utils;
