const units_map = {
  length: {
    m: 1,
    cm: 100,
    mm: 1000,
    inch: 1 / 0.0254,
    ft: 1 / 0.3048,
  },
  mass: {
    ton: 1e-3,
    kg: 1,
  },
  force: {
    n: 1,
  },
  time: {
    s: 1,
    ms: 1e3,
  },
  material_strength: {
    gpa: 1e-9,
    mpa: 1e-6,
    kpa: 1e-3,
    pa: 1,
  },
};

const consistent_units_map = {
  kn: {
    material_strength: "kpa",
    density: "ton/m3",
  },
};

/**
 * Splits a compound unit into its atoms, individual units with a certain power
 * @param {string} compound_unit
 */
const splitCompoundUnits = (compound_unit) => {
  let unit_atoms = compound_unit.split("/");
  let units_object = [];
  if (unit_atoms.length <= 2) {
    unit_atoms.forEach((unit_atom, atom_index) => {
      unit_atom.split("*").forEach((unit_sub_atom) => {
        units_object.push(splitUnitAtom(unit_sub_atom, atom_index === 1));
      });
    });
  } else {
    throw new Error(`Compound unit ${compound_unit} has more than one division which is not supported!`);
  }
  return units_object;
};

/**
 *
 * @param {string} unit_atom - Atom composed by a base unit and a power in that order
 */
const splitUnitAtom = (unit_atom, is_negative_power) => {
  let atom_split = unit_atom.match(/([a-zA-Z]+)([0-9]*)/);
  let power_multiplier = is_negative_power ? -1 : 1;
  return {
    base_unit: atom_split[1],
    power: (atom_split[2] === "" ? 1 : atom_split[2]) * power_multiplier,
    unit_atom,
  };
};

const convert = (value, from, to) => {
  if (typeof value !== "number") throw new Error(`Value to convert is not a number, please parse it first!`);
  let unit_atoms_from = splitCompoundUnits(from);
  let unit_atoms_to = splitCompoundUnits(to);
  let converted_value = value;
  unit_atoms_from.forEach(({ base_unit, power, unit_atom }, atom_index) => {
    let { base_unit: base_unit_to, power: power_to, unit_atom: unit_atom_to } = unit_atoms_to[atom_index];
    if (unit_atom !== unit_atom_to) {
      if (power !== power_to) throw new Error(`Power in ${unit_atom} is different from power in ${unit_atom_to} which is not valid!`);
      converted_value = unit_convert(converted_value, base_unit, base_unit_to, power);
    }
  });
  return converted_value;
};

const unit_convert = (value, from, to, power) => {
  let unit_group_from, unit_group_to;
  Object.entries(units_map).forEach(([group, supported_units]) => {
    if (Object.keys(supported_units).includes(from)) unit_group_from = group;
    if (Object.keys(supported_units).includes(to)) unit_group_to = group;
  });
  if (unit_group_from === undefined) throw new Error(`Unit ${from} is not supported!`);
  if (unit_group_to === undefined) throw new Error(`Unit ${to} is not supported!`);
  if (unit_group_from !== unit_group_to) throw new Error(`Conversion from ${from} to ${to} is not possible!`);
  return (value * units_map[unit_group_to][to] ** power) / units_map[unit_group_from][from] ** power;
};

/**
 *
 * @param {import("../types").s3d_unit} unit - Unit in S3D format
 * @param {import("../types").s3d_unit_key} output_key - Key from S3D units
 */
const getConsistentUnits = (unit, output_key) => {
  if (!consistent_units_map.hasOwnProperty(unit)) throw new Error(`Not supported unit ${unit} for consistent units!`);
  if (!consistent_units_map[unit].hasOwnProperty(output_key))
    throw new Error(`Not supported unit key ${output_key} in unit ${unit} for consistent units!`);
  return consistent_units_map[unit][output_key];
};

export { convert, getConsistentUnits };
