import { distanceBetweenPoints } from "../../utils/geometry.js";
import { convert, getConsistentUnits } from "../../utils/units_converter.js";

let export_issues = {
  sections: [],
  members: [],
  distributed_loads: [],
  supports: [],
  point_loads: [],
  moments: [],
};
function generateInputFile(s3d_model, software_key, software_version) {
  let {
    nodes,
    point_loads,
    moments,
    distributed_loads,
    self_weight,
    load_cases,
    load_combinations,
    sections,
    materials,
    settings: { units },
    members,
    supports,
    plates,
  } = s3d_model;
  /**
   *
   */

  // Preprocess some data
  let { processed_members, processed_nodes, used_sections } = preprocessMembersAndNodes(members, nodes);
  let { processed_sections, processed_materials } = preprocessSectionsAndMaterials(sections, materials, units, used_sections);

  let input_file_str = "";
  input_file_str += getGenericFileHeader();
  // Process load groups
  let load_groups = getAllLoadGroups(point_loads, moments, distributed_loads, self_weight, load_cases[Object.keys(load_cases)[0]]);
  input_file_str += getLoadGroupsAndCasesTables(load_groups);
  // Process the load combinations
  input_file_str += getLoadCombinationsTable(load_combinations);
  // Sections
  input_file_str += getSectionsTables(processed_sections, used_sections, processed_materials);
  // Process the nodes
  input_file_str += getNodesTable(processed_nodes);
  // Process the members
  input_file_str += getMembersTables(processed_members, processed_sections);
  // Process the loads
  input_file_str += getDistributedLoadsTable(distributed_loads, processed_members);

  // Get the gravity value
  let gravity_value = getGravityValue(units.length);
  // Process the materials
  input_file_str += getMaterialsTables(processed_materials, gravity_value);

  // Supports
  input_file_str += getSupportsTables(supports);

  // Point loads and point moments
  input_file_str += getPointLoadsAndPointMomentsTables(point_loads, moments, processed_members);

  // Plates
  let processed_plates = preprocessPlates(plates, processed_materials, units);
  input_file_str += getPlatesTables(processed_plates, units);

  // Closing lines
  input_file_str += getClosingLines(software_key, software_version, units);

  console.log(export_issues);

  return input_file_str;
}

function getGravityValue(length_unit) {
  let gravity_value = 0;
  switch (length_unit) {
    case "m":
      gravity_value = 9.81;
      break;
    case "mm":
      gravity_value = 9810;
      break;
    case "ft":
      gravity_value = 32.185;
      break;
    case "in":
      gravity_value = 32.185;
      break;
    default:
      throw new Error(`Units ${length_unit} is not supported for gravity`);
  }
  return gravity_value;
}

const s3d_to_sap_load_cases_map = {
  default: "Other",
  list: [
    { s3d_match_key: "dead", sap_key: "Dead" },
    { s3d_match_key: "live", sap_key: "Live" },
    { s3d_match_key: "roof live", sap_key: "Roof Live" },
    { s3d_match_key: "seis", sap_key: "Quake" },
    { s3d_match_key: "wind", sap_key: "Wind" },
    { s3d_match_key: "snow", sap_key: "Snow" },
    { s3d_match_key: "acci", sap_key: "Other" },
  ],
};

const s3d_to_sap_material_type_map = {
  default: "Other",
  list: [
    { s3d_match_key: "concrete", sap_key: "Concrete" },
    { s3d_match_key: "aluminium", sap_key: "Aluminium" },
    { s3d_match_key: "other", sap_key: "Other" },
    { s3d_match_key: "steel", sap_key: "Steel" },
  ],
};

const s3d_to_sap_units = {
  list: [
    { s3d_match_key: "m", sap_key: "m" },
    { s3d_match_key: "kn", sap_key: "kN" },
    { s3d_match_key: "degc", sap_key: "C" },
  ],
};

function getSAPEquivalentFromS3D(map_object, s3d_key, is_exact) {
  let final_sap_key = map_object.default;
  if (s3d_key !== undefined) {
    map_object.list.forEach(({ s3d_match_key, sap_key }) => {
      if (is_exact) {
        if (s3d_key === s3d_match_key) final_sap_key = sap_key;
      } else {
        if (s3d_key.includes(s3d_match_key)) final_sap_key = sap_key;
      }
    });
  }
  // Break if there is no default key and the equivalent was not found
  if (final_sap_key === undefined)
    throw new Error(
      `There was no default equivalent and the ${is_exact ? "exact" : "approximate"} equivalent for ${s3d_key} was not found in the map!`
    );
  return final_sap_key;
}

function getTableHeader(title) {
  return `\n\nTABLE:  "${title}"`;
}

function getFullLine(content) {
  return `\n   ${content}`;
}

function getFullIndentedLine(content) {
  return `\n        ${content}`;
}

function getGenericFileHeader() {
  let t = getTableHeader;
  let l = getFullLine;
  let file_str = "";
  file_str += t(`ACTIVE DEGREES OF FREEDOM`);
  file_str += l(`UX=Yes   UY=Yes   UZ=Yes   RX=Yes   RY=Yes   RZ=Yes`);
  file_str += t(`ANALYSIS OPTIONS`);
  file_str += l(`Solver=Advanced   SolverProc=Auto   Force32Bit=No   StiffCase=None   GeomMod=None   HingeOpt="In Elements"`);
  file_str += t(`COORDINATE SYSTEMS`);
  file_str += l(`Name=GLOBAL   Type=Cartesian   X=0   Y=0   Z=0   AboutZ=0   AboutY=0   AboutX=0`);
  return file_str;
}

function getAllLoadGroups(point_loads, moments, distributed_loads, self_weight, load_cases = {}) {
  let load_groups = {};
  function processLoadGroups(loads_obj, is_include_self_weight) {
    Object.values(loads_obj).forEach(({ load_group }) => {
      if (!load_groups.hasOwnProperty(load_group)) {
        // Look for the actual load case if defined in S3D
        let sap_key = getSAPEquivalentFromS3D(s3d_to_sap_load_cases_map, load_cases[load_group], false);
        load_groups[load_group] = { is_include_self_weight, sap_key };
      }
    });
  }
  processLoadGroups(point_loads, false);
  processLoadGroups(moments, false);
  processLoadGroups(distributed_loads, false);
  processLoadGroups(self_weight, true);
  return load_groups;
}

/**
 *
 * @param {*} load_cases
 * @param {Object<string,{sap_key:string, is_include_self_weight:boolean}>} load_groups
 * @returns {string}
 */
function getLoadGroupsAndCasesTables(load_groups) {
  function getLoadCaseLine(name, design_type) {
    return getFullLine(
      `Case=${name}   Type=LinStatic   InitialCond=Zero   DesTypeOpt="Prog Det"   DesignType=${design_type}   DesActOpt="Prog Det"   DesignAct=Other   AutoType=None   RunCase=Yes   GUID=${getGUID()}`
    );
  }
  function getLoadPatternLine(name, design_type, is_include_self_weight) {
    return getFullLine(`LoadPat=${name}   DesignType=${design_type}   SelfWtMult=${is_include_self_weight ? 1 : 0}   GUID=${getGUID()}`);
  }
  function getLoadAssignmentLine(name) {
    return getFullLine(`Case=${name}   LoadType="Load pattern"   LoadName=${name}   LoadSF=1`);
  }
  let load_case_table_definitions = getTableHeader("LOAD CASE DEFINITIONS");
  let load_pattern_table_definitions = getTableHeader("LOAD PATTERN DEFINITIONS");
  let load_assignments_table = getTableHeader("CASE - STATIC 1 - LOAD ASSIGNMENTS");
  Object.entries(load_groups).forEach(([load_group, { sap_key, is_include_self_weight }]) => {
    load_case_table_definitions += getLoadCaseLine(load_group, sap_key);
    load_pattern_table_definitions += getLoadPatternLine(load_group, sap_key, is_include_self_weight);
    load_assignments_table += getLoadAssignmentLine(load_group);
  });
  return `${load_case_table_definitions}${load_pattern_table_definitions}${load_assignments_table}`;
}

function getLoadCombinationsTable(load_combinations) {
  function getLoadCombinationLine(name, case_name, factor) {
    return getFullLine(
      `ComboName=${name}   ComboType="Linear Add"   AutoDesign=No   CaseName=${case_name}   ScaleFactor=${factor}   SteelDesign=None   ConcDesign=Strength   AlumDesign=None   ColdDesign=None   GUID=${getGUID()}`
    );
  }
  let load_combinations_table = getTableHeader("COMBINATION DEFINITIONS");
  Object.values(load_combinations).forEach((load_combo) => {
    let { name, criteria } = load_combo;
    Object.entries(load_combo).forEach(([load_case_name, factor]) => {
      if (load_case_name !== "name" && load_case_name !== "criteria") load_combinations_table += getLoadCombinationLine(name, load_case_name, factor);
    });
  });
  return load_combinations_table;
}

/**
 * - Adds the name if it does not exist
 * - Converts the dimensions to length units
 * - Converts the material properties to consistent units
 * - Filters the not supported sections
 * - Adds the material name
 * - Adds a default section if it is used but does not exist
 * - Adds a default material if no material defined
 * @param {*} sections
 * @param {import("../../types.js").s3d_units_object} units
 * @param {import("../../types.js").s3d_materials_object} materials
 */
function preprocessSectionsAndMaterials(sections, materials, units, used_sections) {
  let processed_sections = {};
  /** @type {import("../../types.js").s3d_materials_object} */
  let processed_materials = JSON.parse(JSON.stringify(materials));
  let { length, section_length } = units;

  // Convert the values in the material properties to CSI consistent units
  Object.entries(processed_materials).forEach(([material_id, data]) => {
    let s3d_force_unit = units.force;
    let s3d_strength_unit = units.material_strength;
    let s3d_density_unit = units.density;
    // Young Modulus
    let csi_strength_unit = getConsistentUnits(s3d_force_unit, "material_strength");
    processed_materials[material_id].elasticity_modulus = convert(
      processed_materials[material_id].elasticity_modulus,
      s3d_strength_unit,
      csi_strength_unit
    );
    // Density
    let csi_density_unit = getConsistentUnits(s3d_force_unit, "density");
    processed_materials[material_id].density = convert(processed_materials[material_id].density, s3d_density_unit, csi_density_unit);
  });

  Object.entries(sections).forEach(([id, section]) => {
    let supported_section = false;
    // Template shapes
    if (section.info) {
      switch (section.info.shape) {
        case "rectangle":
          supported_section = true;
          let { h, b } = section.info.dimensions;
          let base = convert(b, section_length, length);
          let height = convert(h, section_length, length);
          if (section.name === undefined) section.name = `${base}x${height}`;
          section.material_name = processed_materials[section.material_id].name;
          section.info.dimensions = { b: base, h: height };
          break;
        default:
          break;
      }
    }
    if (!supported_section) {
      addExportIssue("sections", id, section.hasOwnProperty("name") ? section.name : "", "no_template_rectangular_section");
    } else {
      processed_sections[id] = Object.assign({}, section);
    }
  });
  return { processed_sections, processed_materials };
}
/**
 * Adds the material name to the plate
 * Converts the thickness to length units (from section_length)
 * Converts the nodes to array if it is an string
 * @param {*} plates
 * @param {*} processed_materials
 */
function preprocessPlates(plates, processed_materials, units) {
  let processed_plates = JSON.parse(JSON.stringify(plates));
  let { length, section_length } = units;
  Object.entries(processed_plates).forEach(
    ([plate_id, { nodes, thickness, material_id, membrane_thickness, shear_thickness, bending_thickness }]) => {
      // Convert to section length
      processed_plates[plate_id].thickness = convert(thickness, section_length, length);
      processed_plates[plate_id].membrane_thickness = membrane_thickness !== null ? convert(membrane_thickness, section_length, length) : thickness;
      processed_plates[plate_id].shear_thickness = shear_thickness !== null ? convert(shear_thickness, section_length, length) : thickness;
      processed_plates[plate_id].bending_thickness = bending_thickness !== null ? convert(bending_thickness, section_length, length) : thickness;
      // Add the material name
      processed_plates[plate_id].material_name = processed_materials[material_id].name;
      // Split the nodes list to an array
      if (typeof nodes === "string") processed_plates[plate_id].nodes = nodes.split(",");
    }
  );
  return processed_plates;
}
/**
 * Adds the member length
 * Adds to each node the property special_node. Set to true if the node is not used and as false if used
 * @param {*} members
 * @param {*} nodes
 */
function preprocessMembersAndNodes(members, nodes) {
  let processed_members = {};
  let processed_nodes = {};
  let used_sections = [];
  let used_nodes = [];
  Object.entries(members).forEach(([id, { node_A, node_B, section_id }]) => {
    let length = distanceBetweenPoints(nodes[node_A], nodes[node_B]);
    processed_members[id] = Object.assign(members[id], { length });
    used_sections.push(section_id);
    used_nodes.push(String(node_A));
    used_nodes.push(String(node_B));
  });
  used_nodes = [...new Set(used_nodes)];
  Object.entries(nodes).forEach(([id, { x, y, z }]) => {
    processed_nodes[id] = {
      x,
      y,
      z,
      special_node: !used_nodes.includes(id),
    };
  });
  return { processed_members, processed_nodes, used_sections };
}

function getSectionsTables(sections) {
  /**
   *
   * @param {*} section_name
   * @param {*} material_name
   * @param {number} base - Already in length units
   * @param {number} height - Already in length units
   * @returns
   */
  const getRectangularShapeLine = (section_name, material_name, base, height) =>
    getFullLine(
      `SectionName=${section_name}   Material=${material_name}   Shape=Rectangular   t3=${height}   t2=${base}   Area=${0}   TorsConst=${0}   I33=${0}   I22=${0}   I23=${0}   AS2=${0}   AS3=${0}   S33=${0}   S22=${0}   Z33=${0}   Z22=${0} _`
    ) +
    getFullIndentedLine(
      `     R33=${0}   R22=${0}   Color=Magenta   FromFile=No   AMod=1   A2Mod=1   A3Mod=1   JMod=1   I2Mod=1   I3Mod=1   MMod=1   WMod=1   Notes=""`
    );

  const getRectangularBeamLine = (section_name) =>
    getFullLine(
      `SectionName=${section_name}   RebarMatL=A615Gr60   RebarMatC=A615Gr60   ReinfConfig=Rectangular   LatReinf=Ties   Cover=0.04   NumBars3Dir=3   NumBars2Dir=3   BarSizeL=#9   BarSizeC=#4   SpacingC=0.15   NumCBars2=3   NumCBars3=3   ReinfType=Design`
    );
  const getTimeDependentLine = (section_name) => getFullLine(`SectionName=${section_name}   TypeSize=Auto   AutoSFSize=1`);
  let frame_section_properties_general_table = getTableHeader("FRAME SECTION PROPERTIES 01 - GENERAL");
  let frame_section_properties_concrete_table = getTableHeader("FRAME SECTION PROPERTIES 03 - CONCRETE BEAM");
  let frame_section_time_dependent_table = getTableHeader("FRAME SECTION PROPERTIES 13 - TIME DEPENDENT");
  Object.entries(sections).forEach(([id, { name, material_name, info }]) => {
    if (info !== undefined) {
      switch (info.shape) {
        case "rectangle":
          let { h, b } = info.dimensions;
          frame_section_properties_general_table += getRectangularShapeLine(name, material_name, b, h);
          frame_section_properties_concrete_table += getRectangularBeamLine(name);
          frame_section_time_dependent_table += getTimeDependentLine(name);
          break;
        default:
          break;
      }
    }
  });
  return `${frame_section_properties_general_table}${frame_section_properties_concrete_table}${frame_section_time_dependent_table}`;
}

function getNodesTable(nodes) {
  function getNodeLine(id, { x, y, z, special_node }) {
    return getFullLine(
      `Joint=${id}   CoordSys=GLOBAL   CoordType=Cartesian   XorR=${x}   Y=${y}   Z=${z}   SpecialJt=${
        special_node ? "Yes" : "No"
      }   GUID=${getGUID()}`
    );
  }
  let table_str = "";
  table_str += getTableHeader("JOINT COORDINATES");
  Object.entries(nodes).forEach(([node_id, node_obj]) => {
    table_str += getNodeLine(node_id, node_obj);
  });
  return table_str;
}

function getMembersTables(members, sections) {
  const getConnectivityLine = (id, node_A, node_B) =>
    getFullLine(`Frame=${id}   JointI=${node_A}   JointJ=${node_B}   IsCurved=No   GUID=${getGUID()}`);
  const getSectionAssignmentLine = (id, section_name) => getFullLine(`Frame=${id}   AutoSelect=N.A.   AnalSect="${section_name}"   MatProp=Default`);
  const getSectionNoneLine = (id) => getFullLine(`Frame=${id}  AnalSect=None`);
  const getAutoMeshLine = (id) => getFullLine(`Frame=${id}   AutoMesh=Yes   AtJoints=Yes   AtFrames=No   NumSegments=0   MaxLength=0   MaxDegrees=0`);
  const getDesignProceduresLine = (id, design_procedure) => getFullLine(`Frame=${id}   DesignProc="${design_procedure}"`);
  const getLoadTransferLine = (id, transfer_load) => getFullLine(`Frame=${id}   Transfer="${transfer_load}"`);
  const getOutputStationLine = (id, station_spacing) =>
    getFullLine(`Frame=${id}   StationType=MaxStaSpcg   MaxStaSpcg=${station_spacing}   AddAtElmInt=Yes   AddAtPtLoad=Yes`);

  let members_connectivity_table = getTableHeader("CONNECTIVITY - FRAME");
  let members_section_table = getTableHeader("FRAME SECTION ASSIGNMENTS");
  let members_auto_mesh_table = getTableHeader("FRAME AUTO MESH ASSIGNMENTS");
  let members_design_procedures_table = getTableHeader("FRAME DESIGN PROCEDURES");
  let members_load_transfer_table = getTableHeader("FRAME LOAD TRANSFER OPTIONS");
  let members_output_stations_table = getTableHeader("FRAME OUTPUT STATION ASSIGNMENTS");

  Object.entries(members).forEach(([id, { node_A, node_B, section_id, type }]) => {
    members_connectivity_table += getConnectivityLine(id, node_A, node_B);
    if (section_id === null && type === "rigid") {
      // Rigid Link
      // TODO - Check if this is the SAP way
      members_section_table += getSectionNoneLine(id);
      members_design_procedures_table += getDesignProceduresLine(id, "No Design");
    } else if (sections[section_id] === undefined) {
      // Section was not imported
      addExportIssue("members", id, section_id, "loaded_default_section_original_not_supported");
      members_section_table += getSectionNoneLine(id);
      members_design_procedures_table += getDesignProceduresLine(id, "No Design");
    } else {
      members_section_table += getSectionAssignmentLine(id, sections[section_id].name);
      members_design_procedures_table += getDesignProceduresLine(id, "From Material");
    }
    members_auto_mesh_table += getAutoMeshLine(id);
    members_load_transfer_table += getLoadTransferLine(id, "Yes");
    members_output_stations_table += getOutputStationLine(id, 0.5);
  });
  return `${members_connectivity_table}${members_section_table}${members_auto_mesh_table}${members_design_procedures_table}${members_load_transfer_table}${members_output_stations_table}`;
}

function getDistributedLoadsTable(distributed_loads, members) {
  const getDistributedLoadLine = (frame_id, load_group, dir, rel_a, rel_b, abs_a, abs_b, value_a, value_b) =>
    getFullLine(
      `Frame=${frame_id}   LoadPat="${load_group}"   CoordSys=GLOBAL   Type=Force   Dir=${dir}   DistType=RelDist   RelDistA=${rel_a}   RelDistB=${rel_b}   AbsDistA=${abs_a}   AbsDistB=${abs_b}   FOverLA=${value_a}   FOverLB=${value_b}   GUID=${getGUID()}`
    );

  let distributed_loads_table = getTableHeader("FRAME LOADS - DISTRIBUTED");

  Object.entries(distributed_loads).forEach(
    ([id, { member, position_A, position_B, load_group, axes, x_mag_A, y_mag_A, z_mag_A, x_mag_B, y_mag_B, z_mag_B }]) => {
      if (axes !== "global") {
        addExportIssue("distributed_loads", id, axes, "no_global_is_not_supported");
      } else {
        let member_length = members[member].length;
        let rel_a = position_A / 100;
        let rel_b = position_B / 100;
        let abs_a = member_length * rel_a;
        let abs_b = member_length * rel_b;
        if (x_mag_A !== 0 || x_mag_B !== 0) {
          distributed_loads_table += getDistributedLoadLine(member, load_group, "X", rel_a, rel_b, abs_a, abs_b, x_mag_A, x_mag_B);
        }
        if (y_mag_A !== 0 || y_mag_B !== 0) {
          distributed_loads_table += getDistributedLoadLine(member, load_group, "Y", rel_a, rel_b, abs_a, abs_b, y_mag_A, y_mag_B);
        }
        if (z_mag_A !== 0 || z_mag_B !== 0) {
          // Gravity is Z downwards, need to invert the load value
          distributed_loads_table += getDistributedLoadLine(member, load_group, "Gravity", rel_a, rel_b, abs_a, abs_b, -z_mag_A, -z_mag_B);
        }
      }
    }
  );
  return `${distributed_loads_table}`;
}

function getMaterialsTables(materials, gravity_value) {
  const getMaterialGeneralLine = (name, type, grade, sym_type) =>
    getFullLine(`Material=${name}   Type=${type}   Grade="${grade}"   SymType=${sym_type}   TempDepend=No   Color=Green   Notes=""`);
  const getBasicMechanicalLine = (name, unit_weight, unit_mass, elastic, shear, poisson, thermal) =>
    getFullLine(
      `Material=${name}   UnitWeight=${unit_weight}   UnitMass=${unit_mass}   E1=${elastic}   G12=${shear}   U12=${poisson}   A1=${thermal}`
    );
  let material_general_table = getTableHeader("MATERIAL PROPERTIES 01 - GENERAL");
  let material_basic_mechanical_table = getTableHeader("MATERIAL PROPERTIES 02 - BASIC MECHANICAL PROPERTIES");
  Object.entries(materials).forEach(([id, material]) => {
    let material_class = getSAPEquivalentFromS3D(s3d_to_sap_material_type_map, material.class, true);
    material_general_table += getMaterialGeneralLine(material.name, material_class, "", "Isotropic");
    let unit_mass = material.density;
    let unit_weight = unit_mass * gravity_value;
    let poisson = material.poissons_ratio;
    let elastic = material.elasticity_modulus;
    let shear = elastic / (2 * (1 + poisson));
    let thermal = 0.000001;
    material_basic_mechanical_table += getBasicMechanicalLine(material.name, unit_weight, unit_mass, elastic, shear, poisson, thermal);
  });
  // Add default rebar material
  material_general_table += getMaterialGeneralLine("A615Gr60", "Rebar", "Grade 60", "Uniaxial");
  material_basic_mechanical_table += getBasicMechanicalLine("A615Gr60", 77, 7.84, 199947978, 0, 0, 0.000001);
  return `${material_general_table}${material_basic_mechanical_table}`;
}

function getSupportsTables(supports) {
  const getJointRestraintLine = (node_id, { u1, u2, u3, r1, r2, r3 }) =>
    getFullLine(`Joint=${node_id}   U1=${u1}   U2=${u2}   U3=${u3}   R1=${r1}   R2=${r2}   R3=${r3}`);
  let joint_restraints_table = getTableHeader("JOINT RESTRAINT ASSIGNMENTS");
  Object.entries(supports).forEach(([id, { restraint_code, type, node }]) => {
    if (type !== "node") {
      addExportIssue("supports", id, { type }, "not_supported_type");
      return;
    }
    let dof_restraints = {
      u1: "No",
      u2: "No",
      u3: "No",
      r1: "No",
      r2: "No",
      r3: "No",
    };
    Object.keys(dof_restraints).forEach((dof_key, dof_index) => {
      switch (restraint_code[dof_index]) {
        case "F":
          dof_restraints[dof_key] = "Yes";
          break;
        case "R":
          break;
        default:
          addExportIssue("supports", id, { restraint_code: restraint_code[dof_index], dof_key }, "not_supported_restraint_loaded_fixed");
          break;
      }
    });
    joint_restraints_table += getJointRestraintLine(node, dof_restraints);
  });
  return `${joint_restraints_table}`;
}

function getPointLoadsAndPointMomentsTables(point_loads, moments, members) {
  const getFramePointLoadLine = (frame_id, load_group, dir, abs_dist, force, is_moment) =>
    getFullLine(
      `Frame=${frame_id}   LoadPat="${load_group}"   CoordSys=GLOBAL   Type=${
        is_moment ? "Moment" : "Force"
      }   Dir=${dir}   DistType=AbsDist   AbsDist=${abs_dist}   ${is_moment ? "Moment" : "Force"}=${force}   GUID=${getGUID()}`
    );
  const getNodePointLoadLine = (node_id, load_group, f1, f2, f3, m1, m2, m3) =>
    getFullLine(
      `Joint=${node_id}   LoadPat=${load_group}   CoordSys=GLOBAL   F1=${f1}   F2=${f2}   F3=${f3}   M1=${m1}   M2=${m2}   M3=${m3}   GUID=${getGUID()}`
    );
  let frame_point_loads_table = getTableHeader("FRAME LOADS - POINT");
  let node_point_loads_table = getTableHeader("JOINT LOADS - FORCE");
  Object.entries(point_loads).forEach(([id, { x_mag, y_mag, z_mag, load_group, type, node, member, position }]) => {
    if (type === "N") {
      node_point_loads_table += getNodePointLoadLine(node, load_group, x_mag, y_mag, z_mag, 0, 0, 0);
    } else if (type === "M") {
      let member_length = members[member].length;
      let rel_dist = position / 100;
      let abs_dist = member_length * rel_dist;
      if (x_mag !== 0) frame_point_loads_table += getFramePointLoadLine(member, load_group, "X", abs_dist, x_mag);
      if (y_mag !== 0) frame_point_loads_table += getFramePointLoadLine(member, load_group, "Y", abs_dist, y_mag);
      if (z_mag !== 0) frame_point_loads_table += getFramePointLoadLine(member, load_group, "Gravity", abs_dist, -z_mag);
    } else {
      addExportIssue("point_loads", id, type, "not_supported_type");
    }
  });
  Object.entries(moments).forEach(([id, { x_mag, y_mag, z_mag, load_group, type, node, member, position }]) => {
    if (type === "N") {
      node_point_loads_table += getNodePointLoadLine(node, load_group, 0, 0, 0, x_mag, y_mag, z_mag);
    } else if (type === "M") {
      let member_length = members[member].length;
      let rel_dist = position / 100;
      let abs_dist = member_length * rel_dist;
      if (x_mag !== 0) frame_point_loads_table += getFramePointLoadLine(member, load_group, "X", abs_dist, x_mag, true);
      if (y_mag !== 0) frame_point_loads_table += getFramePointLoadLine(member, load_group, "Y", abs_dist, y_mag, true);
      if (z_mag !== 0) frame_point_loads_table += getFramePointLoadLine(member, load_group, "Z", abs_dist, z_mag, true);
    } else {
      addExportIssue("moments", id, type, "not_supported_type");
    }
  });
  return `${frame_point_loads_table}${node_point_loads_table}`;
}

function getPlatesTables(processed_plates, units) {
  let { length } = units;
  let area_section_properties_table = getTableHeader("AREA SECTION PROPERTIES");
  let area_design_params_table = getTableHeader("AREA SECTION PROPERTY DESIGN PARAMETERS");
  let area_time_dependent_table = getTableHeader("AREA SECTION PROPERTY - TIME DEPENDENT");
  let area_connectivity_table = getTableHeader("CONNECTIVITY - AREA");
  let area_section_assignment_table = getTableHeader("AREA SECTION ASSIGNMENTS");
  const getPropertyLine = (name, thickness, material) =>
    getFullLine(
      `Section="${name}"   Material="${material}"   MatAngle=0   AreaType=Shell   Type=Shell-Thin   DrillDOF=Yes   Thickness=${thickness}   BendThick=${thickness}   Color=Yellow   F11Mod=1   F22Mod=1   F12Mod=1   M11Mod=1   M22Mod=1   M12Mod=1   V13Mod=1   V23Mod=1   MMod=1   WMod=1   GUID=${getGUID()}   Notes=""`
    );
  const getDesignParamsLine = (name) => getFullLine(`Section="${name}"   RebarMat=None   RebarOpt=Default`);
  const getTimeDependentLine = (name) => getFullLine(`Section="${name}"   TypeSize=Auto   AutoSFSize=1`);
  const getMultiNodeConnectivityLine = (plate_id, nodes, order, total_nodes) => {
    let line = `Area=${plate_id}`;
    if (order === 1) line += `   NumJoints=${total_nodes}`;
    nodes.forEach((node, node_i) => {
      line += `   Joint${node_i + 1}=${node}`;
    });
    line += `   Order=${order}`;
    if (order === 1) line += `   GUID=${getGUID()}`;
    return getFullLine(line);
  };
  const getSectionAssignmentLine = (plate_id, section_name) => getFullLine(`Area=${plate_id}   Section="${section_name}"   MatProp=Default`);
  let plate_sections_strings = [];
  Object.entries(processed_plates).forEach(
    ([plate_id, { nodes, thickness, material_name, membrane_thickness, shear_thickness, bending_thickness }]) => {
      let section_name =
        `PLATE ${thickness}${length}` +
        (thickness !== membrane_thickness ? `M${membrane_thickness}${length}` : "") +
        (thickness !== shear_thickness ? `S${shear_thickness}${length}` : "") +
        (thickness !== bending_thickness ? `B${bending_thickness}${length}` : "");
      // Section properties
      let plate_section_line = getPropertyLine(section_name, thickness, material_name);
      if (!plate_sections_strings.includes(plate_section_line)) {
        area_section_properties_table += plate_section_line;
        area_design_params_table += getDesignParamsLine(section_name);
        area_time_dependent_table += getTimeDependentLine(section_name);
      }
      // Connectivity
      for (let sub_plate_i = 1; sub_plate_i <= Math.ceil(nodes.length / 4); sub_plate_i++) {
        let sub_nodes = nodes.slice((sub_plate_i - 1) * 4, sub_plate_i * 4);
        area_connectivity_table += getMultiNodeConnectivityLine(plate_id, sub_nodes, sub_plate_i, nodes.length);
      }
      // Section Assignment
      area_section_assignment_table += getSectionAssignmentLine(plate_id, section_name);
    }
  );
  return `${area_section_properties_table}${area_design_params_table}${area_time_dependent_table}${area_connectivity_table}${area_section_assignment_table}`;
}

function getConstraintsTables() {
  const getConstraintLine = (name, { ux, uy, uz, rx, ry, rz }) =>
    getFullLine(`Name=${name}   CoordSys=GLOBAL   UX=${ux}   UY=${uy}   UZ=${uz}   RX=${rx}   RY=${ry}   RZ=${rz}`);
  const getAssignmentLine = (node_id, constraint_name) => getFullLine(`Joint=${node_id}   Constraint=${constraint_name}`);
  let constraints_definitions_table = getTableHeader("CONSTRAINT DEFINITIONS - BODY");
  let constraints_assignment_table = getTableHeader("JOINT CONSTRAINT ASSIGNMENTS");
}

function getClosingLines(software_key, software_version, units) {
  let { force, length, temperature } = units;
  force = getSAPEquivalentFromS3D(s3d_to_sap_units, force, true);
  length = getSAPEquivalentFromS3D(s3d_to_sap_units, length, true);
  temperature = getSAPEquivalentFromS3D(s3d_to_sap_units, temperature, true);
  let program_control_table = getTableHeader("PROGRAM CONTROL");
  program_control_table += getFullLine(
    `ProgramName=${software_key}   Version=${software_version}   CurrUnits="${force}, ${length}, ${temperature}"   SteelCode="AISC 360-16"   ConcCode="ACI 318-14"   AlumCode="AA-ASD 2000"   ColdCode=AISI-ASD96   RegenHinge=Yes`
  );
  let last_line = `\n\nEND TABLE DATA\n`;
  return `${program_control_table}${last_line}`;
}

function getGUID() {
  let spaces = [8, 4, 4, 17];
  let guid = "";
  let char_set = "abcdefghijklmnopqrstuvwxyz0123456789";
  spaces.forEach((space_length, space_i) => {
    for (let i = 0; i < space_length; i++) {
      guid += char_set[Math.round(Math.random() * (char_set.length - 1))];
    }
    if (space_i < spaces.length - 1) guid += "-";
  });

  return guid;
}

function addExportIssue(key, id, info, reason) {
  if (!export_issues.hasOwnProperty(key)) throw new Error(`There is no key ${key} available in the export issues object!`);
  export_issues[key].push({ id, info, reason });
}

export default generateInputFile;
