import { convert } from "./units_converter.js";

/**
 *
 * @param {import("../types").s3d_model} model
 * @param {{section_length: string}} target_units_obj
 */
function convertModel(model, target_units_obj) {
  const source_units = model.settings.units.section_length;
  const target_units = target_units_obj.section_length;
  model.sections = Object.fromEntries(
    Object.entries(model.sections).map(([section_id, section_data]) => [
      section_id,
      { ...section_data, info: { ...section_data.info, dimensions: convertObject(section_data.info.dimensions, source_units, target_units) } },
    ])
  );
  return model;
}

function convertObject(object, source_units, target_units) {
  return Object.fromEntries(Object.entries(object).map(([key, value]) => [key, convert(value, source_units, target_units)]));
}

export { convertModel };
