import { distanceBetweenPoints } from "../../utils/geometry.js";
import { findNextAvailableID, getEmptyStructuralModel } from "../../utils/model.js";

/**
 *
 * @param {string} dxf_string
 * @returns {import("../../types").s3d_model}
 */
export const dxf2s3d = (dxf_string) => {
  let log = [];
  let dxf_key = "AcDbLine";
  let key_map = {
    x_i: { dxf_key: 10, type: "number" },
    y_i: { dxf_key: 20, type: "number" },
    z_i: { dxf_key: 30, type: "number" },
    x_j: { dxf_key: 11, type: "number" },
    y_j: { dxf_key: 21, type: "number" },
    z_j: { dxf_key: 31, type: "number" },
  };
  /** @type {{x_i: number, y_i: number, z_i: number, x_j: number, y_j: number, z_j: number}[]} */
  let lines = [];
  let regex = buildRegex(dxf_key, key_map);
  let all_matches = [...dxf_string.matchAll(regex)];
  all_matches.forEach((match_i) => {
    let match_object = {};
    Object.entries(key_map).forEach(([key, { type }], key_index) => {
      let dxf_value = match_i[key_index + 1];
      switch (type) {
        case "number":
          match_object[key] = Number(dxf_value);
          break;
        default:
          throw new Error(`Unknown dxf value type ${type}`);
          break;
      }
    });
    lines.push(match_object);
  });

  let s3d_model = getEmptyStructuralModel();

  let { nodes, members } = s3d_model;

  lines.forEach(({ x_i, y_i, z_i, x_j, y_j, z_j }) => {
    /** @type {import("../../types").s3d_node} */
    let node_A_obj = { x: x_i, y: y_i, z: z_i };
    let node_A = nodeAlreadyExists(nodes, node_A_obj);
    if (node_A == undefined) {
      node_A = findNextAvailableID(nodes);
      nodes[node_A] = node_A_obj;
    }
    let node_B_obj = { x: x_j, y: y_j, z: z_j };
    let node_B = nodeAlreadyExists(nodes, node_B_obj);
    if (node_B == undefined) {
      node_B = findNextAvailableID(nodes);
      nodes[node_B] = node_B_obj;
    }

    members[findNextAvailableID(members)] = { node_A, node_B };
  });

  return s3d_model;
};

const nodeAlreadyExists = (nodes, new_node) => {
  let threshold = 0.01;
  let existing_node_id;
  Object.entries(nodes).forEach(([node_id, node_obj]) => {
    if (distanceBetweenPoints(node_obj, new_node) < threshold) existing_node_id = Number(node_id);
  });
  return existing_node_id;
};

const buildRegex = (dxf_key, key_map) => {
  let regex_str = `${dxf_key}\r\n`;
  Object.values(key_map).forEach(({ dxf_key: sub_key }) => {
    regex_str += ` ${sub_key}\r\n([0-9.]*)\r\n`;
  });
  return new RegExp(regex_str, "g");
};
