import { findNextAvailableID, getEmptyStructuralModel } from "../../utils/model.js";
import { convert } from "../../utils/units_converter.js";

/**
 *
 * @param {string} csi_string
 * @returns {import("../../types.js").s3d_model}
 */
export const csi2s3d = (csi_string) => {
  let log = [];

  let s3d_model = getEmptyStructuralModel();
  let {
    nodes,
    members,
    supports,
    plates,
    settings: { units },
  } = s3d_model;

  // key: CSI ID    value: S3D ID
  let csi_to_s3d_nodes = {};
  let csi_to_s3d_plates = {};
  let csi_program_control = {};

  /** @type {Object.<string, Object.<string, string|number>>} */
  let csi_area_sections = {};

  let program_control_key_map = {
    program_name: { csi_key: "ProgramName", type: "string" },
    current_units: { csi_key: "CurrUnits", type: "string" },
  };
  let program_control_key_gather = {
    length: { csi_keys: ["current_units"], gather_function: (csi_values) => csi_values[0].split(", ")[1] },
  };
  extractPropertiesFromCSIString("PROGRAM CONTROL", csi_string, program_control_key_map, csi_program_control, program_control_key_gather);

  // Bring to the root
  csi_program_control = csi_program_control[Object.keys(csi_program_control)[0]];

  let nodes_key_map = {
    id: { csi_key: "Joint", type: "number", map_to: csi_to_s3d_nodes },
    x: { csi_key: "XorR", type: "number" },
    y: { csi_key: "Y", type: "number" },
    z: { csi_key: "Z", type: "number" },
  };
  extractPropertiesFromCSIString("JOINT COORDINATES", csi_string, nodes_key_map, nodes);

  let members_key_map = {
    id: { csi_key: "Frame", type: "number" },
    node_A: { csi_key: "JointI", type: "number", map_from: csi_to_s3d_nodes },
    node_B: { csi_key: "JointJ", type: "number", map_from: csi_to_s3d_nodes },
  };
  extractPropertiesFromCSIString("CONNECTIVITY - FRAME", csi_string, members_key_map, members);

  let supports_key_map = {
    node: { csi_key: "Joint", type: "number", map_from: csi_to_s3d_nodes },
    U1: { csi_key: "U1", type: "string" },
    U2: { csi_key: "U2", type: "string" },
    U3: { csi_key: "U3", type: "string" },
    R1: { csi_key: "R1", type: "string" },
    R2: { csi_key: "R2", type: "string" },
    R3: { csi_key: "R3", type: "string" },
  };
  let supports_key_gather = {
    restraint_code: {
      csi_keys: ["U1", "U2", "U3", "R1", "R2", "R3"],
      gather_function: (csi_values) => csi_values.map((csi_value) => (csi_value == "Yes" ? "F" : "R")).join(""),
    },
  };
  extractPropertiesFromCSIString("JOINT RESTRAINT ASSIGNMENTS", csi_string, supports_key_map, supports, supports_key_gather);

  let plates_section_key_map = {
    Section: { csi_key: "Section", type: "string", use_as_key: true },
    thickness: { csi_key: "Thickness", type: "number" },
  };
  extractPropertiesFromCSIString("AREA SECTION PROPERTIES", csi_string, plates_section_key_map, csi_area_sections);

  let plates_key_map = {
    id: { csi_key: "Area", type: "number", map_to: csi_to_s3d_plates, use_as_key: true },
    Joint1: { csi_key: "Joint1", type: "number", optional: true, map_from: csi_to_s3d_nodes },
    Joint2: { csi_key: "Joint2", type: "number", optional: true, map_from: csi_to_s3d_nodes },
    Joint3: { csi_key: "Joint3", type: "number", optional: true, map_from: csi_to_s3d_nodes },
    Joint4: { csi_key: "Joint4", type: "number", optional: true, map_from: csi_to_s3d_nodes },
  };
  let plates_key_gather = {
    nodes: {
      csi_keys: ["Joint1", "Joint2", "Joint3", "Joint4"],
      gather_function: (csi_values, s3d_previous_values) => {
        if (s3d_previous_values == undefined) {
          return csi_values.filter((position) => position != undefined);
        } else {
          return [...s3d_previous_values, ...csi_values.filter((position) => position != undefined)];
        }
      },
    },
  };
  extractPropertiesFromCSIString("CONNECTIVITY - AREA", csi_string, plates_key_map, plates, plates_key_gather, { assign_to_existing: true });

  let plates_section_assign_key_map = {
    id: { csi_key: "Area", type: "string", map_from: csi_to_s3d_plates, use_as_key: true },
    thickness: {
      csi_key: "Section",
      type: "string",
      compound_map_from: { source_obj: csi_area_sections, source_key: "thickness" },
      convert_obj: { from: csi_program_control.length, to: units.section_length },
    },
  };
  extractPropertiesFromCSIString("AREA SECTION ASSIGNMENTS", csi_string, plates_section_assign_key_map, plates, undefined, {
    assign_to_existing: true,
  });

  return s3d_model;
};

/**
 *
 * @param {string} csi_table_name Title of the CSI table in the input file. Example: JOINT RESTRAINT ASSIGNMENTS
 * @param {string} csi_string Full input file
 * @param {Object.<string, {csi_key: string, type: "number"|"string", map_from: Object.<string, string>, compound_map_from: {source_obj: object, source_key: string}, use_as_key: boolean, convert_obj: {from: string, to: string}, map_to: Object.<string, string>, optional: boolean}>} key_map
 * @param {Object.<string, object>} target_s3d_object
 * @param {Object.<string,{csi_keys: string[], gather_function: function(string[])}>} key_gather
 * @param {{assign_to_existing: boolean}}
 */
const extractPropertiesFromCSIString = (csi_table_name, csi_string, key_map, target_s3d_object, key_gather, { assign_to_existing = false } = {}) => {
  // Isolate the table from the full string
  let table_regex = buildRegexToGetTable(csi_table_name);
  let all_table_matches = [...csi_string.matchAll(table_regex)];
  if (all_table_matches.length > 1) throw new Error(`Table ${csi_table_name} is present more than once in the input file!`);
  let csi_table_string = all_table_matches[0][0];

  // Isolate the lines and then extract the properties one by one
  let all_table_lines = csi_table_string.split("\n\n")[0]; // Remove the start of the next table
  all_table_lines = all_table_lines.split("\n").slice(1, all_table_lines.length); // Remove the table header
  if (all_table_lines.length == 0) console.error(`Did not find any occurrences in ${csi_table_name}`);

  all_table_lines.forEach((table_line) => {
    let match_object = {};
    let s3d_element_id = findNextAvailableID(target_s3d_object);
    Object.entries(key_map).forEach(([key, { csi_key, type, map_to, map_from, compound_map_from, use_as_key, convert_obj, optional }]) => {
      let csi_value = getCsiValue(table_line, { csi_key, type });
      if (csi_value == undefined) {
        if (optional) return;
        throw new Error(`Did not find matches for ${csi_key} of type ${type} within:\n${table_line}`);
      }
      switch (type) {
        case "number":
          csi_value = Number(csi_value);
          break;
        case "string":
          csi_value = String(csi_value);
          break;
        default:
          throw new Error(`Unknown value type ${type}`);
          break;
      }
      match_object[key] = csi_value;
      if (map_from != undefined) match_object[key] = map_from[csi_value];
      if (compound_map_from != undefined) {
        let { source_obj, source_key } = compound_map_from;
        let mapped_csi_value = source_obj[csi_value][source_key];
        match_object[key] = mapped_csi_value;
      }
      // Perform unit conversion if required
      if (convert_obj != undefined) {
        let { from, to } = convert_obj;
        match_object[key] = convert(match_object[key], from, to);
      }

      if (use_as_key) s3d_element_id = match_object[key];
      if (map_to != undefined) map_to[match_object[key]] = s3d_element_id;
      if (map_to != undefined || use_as_key) delete match_object[key];
    });

    // Store the match object in the target object
    if (target_s3d_object[s3d_element_id] != undefined && !assign_to_existing)
      throw new Error(`The ID ${s3d_element_id} is already taken in the target object!`);
    if (target_s3d_object[s3d_element_id] == undefined) target_s3d_object[s3d_element_id] = {};
    if (assign_to_existing) {
      Object.assign(target_s3d_object[s3d_element_id], match_object);
    } else {
      target_s3d_object[s3d_element_id] = match_object;
    }

    // Apply the key gather on the recently added object in the target
    if (key_gather != undefined) {
      let s3d_object = target_s3d_object[s3d_element_id];
      Object.entries(key_gather).forEach(([s3d_key, { csi_keys, gather_function }]) => {
        let csi_new_values = csi_keys.map((csi_key) => s3d_object[csi_key]);
        let s3d_previous_values = s3d_object[s3d_key];
        s3d_object[s3d_key] = gather_function(csi_new_values, s3d_previous_values);
        csi_keys.forEach((csi_key) => {
          delete s3d_object[csi_key];
        });
      });
    }
  });
};

const buildRegexToGetTable = (csi_table) => {
  let regex_str = `TABLE:  "${csi_table}"\n.*?(?:TABLE:  |END TABLE DATA)`;
  return new RegExp(regex_str, "gs");
};

/**
 *
 * @param {string} csi_string
 * @param {*} param1
 * @returns
 */
const getCsiValue = (csi_string, { csi_key, type }) => {
  let csi_value;
  let matches_array;
  switch (type) {
    case "number":
      matches_array = [...csi_string.matchAll(new RegExp(`.*${csi_key}=([0-9.]*)(?: {3}|$).*`, "g"))];
      break;
    case "string":
      matches_array = [...csi_string.matchAll(new RegExp(`.*${csi_key}="*([A-Za-z0-9 \.,]*)"*(?: {3}|$).*`, "g"))];
      break;
    default:
      throw new Error(`Unknown value type ${type}`);
      break;
  }
  if (matches_array.length > 0) csi_value = matches_array[0][1];
  return csi_value;
};
